const f=t=>Math.max(0,Math.min(1,t));function C(t){const s=t.time();for(let e=0;e<t.height;e+=1)for(let n=0;n<t.width;n+=1){const a=n/(t.width-1)-.5,o=e/(t.height-1)-.5;t.noise(n*.16,e*.1,s*.62);const r=t.noise(n*.06+4,e*.21,s*.31);let c=11,i=5,l=20+r*13;const M=Math.atan2(o/.12,a/.3),u=Math.hypot(a/.3,o/.12),y=t.noise(Math.cos(M)*2.9+3,Math.sin(M)*2.9+3,s*.48),d=Math.abs(Math.sin(M*7+s*1.1))*.38,x=1.03+y*.78+d,m=f((x-u)*1.5);if(m>0){const h=f(m*.75+r*.25);c=65+h*190,i=7+h*155,l=4+h*23}const g=.31,b=.012+.115*Math.pow(Math.max(0,1-Math.abs(a)/g),.62);if(Math.abs(a)<g&&Math.abs(o)<b){const h=Math.abs(o)/b,w=f(1-h*h),p=t.noise(n*.3,e*.3,s*.12);c=255,i=116+w*132,l=9+p*23;const E=.017+Math.sin(o*42+s*1.8)*.003;(a/E)**2+(o/.13)**2<1&&(c=13,i=3,l=9)}t.pixel(n,e,t.rgb(c,i,l))}}export{C as draw};
